cards.solution:
const produk = {
  nama: "Kopi",
  harga: 20000,
  stok: 5,
  jual(jumlah) {
    this.stok -= jumlah;
    return this.harga * jumlah;
  },
};
const total = produk.jual(2);
console.log(`Terjual 2 ${produk.nama}, total ${total}`);
console.log(`Sisa stok: ${produk.stok}`);
